import storefront from './storefront-original.mjs';
const pages={"/about.html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#0b0b0e\">\n<meta name=\"robots\" content=\"index, follow, max-image-preview:large\">\n<title>About ASRYO | Independent Indian Streetwear Brand</title>\n<meta name=\"description\" content=\"Learn about ASRYO, an independent Indian streetwear label exploring original oversized T-shirt designs, graphic expression and Drop 001 concept collections.\">\n<link rel=\"canonical\" href=\"https://asryo.com/about.html\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:site_name\" content=\"ASRYO\">\n<meta property=\"og:title\" content=\"About ASRYO | Independent Streetwear\">\n<meta property=\"og:description\" content=\"Meet ASRYO: original oversized streetwear concepts, individual expression and a first collection in development.\">\n<meta property=\"og:url\" content=\"https://asryo.com/about.html\">\n<meta property=\"og:image\" content=\"https://asryo.com/assets/asryo-speed-division-front.webp\">\n<script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"AboutPage\",\"name\":\"About ASRYO\",\"url\":\"https://asryo.com/about.html\",\"description\":\"About the ASRYO independent Indian streetwear label and its original clothing design concepts.\",\"isPartOf\":{\"@type\":\"WebSite\",\"name\":\"ASRYO\",\"url\":\"https://asryo.com/\"}}</script>\n<link rel=\"icon\" href=\"/assets/asryo-black-favicon.png\" type=\"image/png\">\n<style>\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#0b0b0e;color:#f4f1ee;font:16px/1.7 system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}a{color:inherit}header{border-bottom:1px solid #343036;display:flex;align-items:center;justify-content:space-between;gap:24px;padding:22px max(22px,calc((100vw - 1120px)/2))}.brand{font-size:25px;letter-spacing:.23em;font-weight:850;text-decoration:none}nav{display:flex;flex-wrap:wrap;gap:22px;font-size:13px;text-transform:uppercase;letter-spacing:.09em}nav a{text-decoration:none}nav a:hover,.button:hover{text-decoration:underline}main{max-width:1120px;padding:64px 22px 110px;margin:auto}.eyebrow{letter-spacing:.22em;text-transform:uppercase;font-size:12px;font-weight:750;color:#ee777b}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:36px;align-items:center;border-bottom:1px solid #343036;padding-bottom:76px}h1{font-size:clamp(47px,7vw,96px);line-height:1.03;letter-spacing:-.07em;margin:0 0 23px}h2{font-size:clamp(28px,3vw,44px);line-height:1.18;letter-spacing:-.045em;margin:0 0 20px}p{max-width:66ch;color:#d4ccd0}strong{color:#fff}.hero img{width:100%;height:auto;display:block;object-fit:cover;background:#211d1e}.sections{display:grid;grid-template-columns:1fr 1fr;gap:50px 85px;padding:70px 0}.sections article{border-top:1px solid #51484d;padding-top:25px}.button{display:inline-block;border:1px solid #f4f1ee;padding:13px 24px;text-decoration:none;text-transform:uppercase;letter-spacing:.12em;font-weight:750;font-size:12px;margin:16px 16px 0 0}.muted{color:#afa7ab;font-size:14px}footer{border-top:1px solid #343036;padding:24px max(22px,calc((100vw - 1120px)/2));display:flex;flex-wrap:wrap;justify-content:space-between;gap:18px;color:#aea6ab;font-size:13px}footer a{margin-right:18px}a:focus-visible{outline:3px solid #ff7979;outline-offset:4px}@media(max-width:700px){.hero,.sections{grid-template-columns:1fr}main{padding-top:46px}.hero{padding-bottom:46px}.sections{gap:25px;padding:45px 0}header{padding:18px 22px;align-items:flex-start;flex-direction:column}nav{gap:15px}}\n</style>\n</head>\n<body>\n<header>\n<a class=\"brand\" href=\"/\" aria-label=\"ASRYO home\">ASRYO</a>\n<nav aria-label=\"Primary navigation\"><a href=\"/\">Home</a><a href=\"/#featured\">T-shirt concepts</a><a href=\"/#lookbook\">Drop 001</a><a href=\"/vote#privacy\">Vote &amp; privacy</a></nav>\n</header>\n<main>\n<section class=\"hero\">\n<div><p class=\"eyebrow\">ASRYO / Independent Indian streetwear</p><h1>Made for your<br>own direction.</h1><p>ASRYO is an independent streetwear label exploring oversized silhouettes, original artwork and the space between motorsport energy, typography and everyday expression.</p><p>We are building a visual language around individuality: considered shapes, bold graphic stories and designs that can stand on their own. Our first collection is currently being developed and shown as a preview.</p><a class=\"button\" href=\"/#featured\">Explore design concepts</a></div>\n<img src=\"/assets/asryo-speed-division-front.webp\" width=\"720\" height=\"900\" alt=\"ASRYO Speed Division original oversized T-shirt design concept\">\n</section>\n<div class=\"sections\">\n<article><p class=\"eyebrow\">01 / Our direction</p><h2>Originality over repetition.</h2><p>ASRYO begins with original graphic ideas. Each concept explores its own visual mood, from racing-inspired artwork to expressive typography and darker illustration. Rather than presenting unverified garments as finished inventory, we share work-in-progress previews while samples and product details are developed.</p></article>\n<article><p class=\"eyebrow\">02 / The fit</p><h2>Built around oversized style.</h2><p>Relaxed silhouettes are the starting point for our design work. Final fabric composition, GSM, measurements, print method and care instructions will be announced only after physical samples have been checked. Images on this website may be AI-generated design mockups, not photographs of manufactured products.</p></article>\n<article><p class=\"eyebrow\">03 / Drop 001</p><h2>The first chapter.</h2><p>Drop 001 brings together original ASRYO streetwear concepts including Speed Division and Dream Future. You can explore front and back designs, study the graphics and follow the evolution of the collection as it moves toward production.</p><p><a href=\"/speed-division.html\">Speed Division concept</a> · <a href=\"/dream-future.html\">Dream Future concept</a></p></article>\n<article><p class=\"eyebrow\">04 / Launch status</p><h2>Concepts today. Details to come.</h2><p>ASRYO is in pre-launch development. Online orders are not open. We do not claim confirmed stock, garment specifications, delivery dates, selling prices or return terms until they are ready to publish. This keeps the difference between an idea and a finished product clear.</p><p><a href=\"/vote#privacy\">Share your design preference</a></p></article>\n</div>\n<p class=\"muted\">This page describes ASRYO's current brand direction and design previews. It does not represent an offer to sell a product.</p>\n<a class=\"button\" href=\"/vote\">Choose our first drop</a><a class=\"button\" href=\"/\">Return to ASRYO</a>\n</main>\n<footer><span>© 2026 ASRYO. Original streetwear concepts.</span><span><a href=\"/\">Home</a><a href=\"/vote#privacy\">Policies</a><a href=\"/sitemap.xml\">Sitemap</a></span></footer>\n</body>\n</html>\n", "/vote": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Choose the First ASRYO Drop | Streetwear Design Vote</title><meta name=\"description\" content=\"Which ASRYO concept would you wear? Choose Speed Division, Dream Future or Shadowbound and help shape our first streetwear collection.\"><meta name=\"robots\" content=\"index, follow, max-image-preview:large\"><link rel=\"canonical\" href=\"https://asryo.com/vote\"><meta property=\"og:title\" content=\"Choose the first ASRYO drop\"><meta property=\"og:description\" content=\"Three streetwear concepts. Which would you wear? Share your preference.\"><meta property=\"og:image\" content=\"https://asryo.com/assets/asryo-drop-001-lookbook.webp\"><meta property=\"og:url\" content=\"https://asryo.com/vote\"><meta property=\"og:type\" content=\"website\"><style>*{box-sizing:border-box}body{margin:0;background:#0b0b0e;color:#f6f2ef;font:16px/1.65 system-ui,sans-serif}a{color:inherit}header,main,footer{max-width:1180px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;gap:24px;border-bottom:1px solid #454045}header a{text-decoration:none}nav{display:flex;gap:20px}.brand{font-weight:850;letter-spacing:.2em}h1{font-size:clamp(44px,7vw,86px);line-height:1.03;letter-spacing:-.05em;max-width:850px;margin:25px 0}h2{font-size:26px;margin:12px 0}.intro{max-width:750px;color:#d4ccd0}.eyebrow{color:#ee9296;letter-spacing:.17em;text-transform:uppercase;font-size:14px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;margin:35px 0}.card{min-width:0;display:block;border:1px solid #51484d;padding:14px;cursor:pointer;border-radius:4px}.card:has(input:checked){border:2px solid #ee9296;padding:13px;background:#251b20}.card img{width:100%;aspect-ratio:4/5;object-fit:cover;display:block;background:#201b1f}.card span{display:block;color:#d4ccd0}.card input{width:20px;height:20px;accent-color:#ee9296;margin:15px 8px 0 0}.card strong{font-size:21px}.actions{display:flex;flex-wrap:wrap;gap:14px}button,.button{font:600 16px system-ui;padding:15px 24px;background:#f6f2ef;color:#111;border:1px solid #f6f2ef;cursor:pointer;text-decoration:none;display:inline-block}.secondary{background:transparent;color:#f6f2ef}button:disabled{opacity:.6;cursor:wait}button[hidden]{display:none}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #ee9296;outline-offset:5px}fieldset{border:0;padding:0;margin:0}legend{font-weight:650;font-size:20px}.privacy{border-top:1px solid #51484d;margin-top:45px;padding-top:25px;max-width:850px;color:#d4ccd0}.trap{position:absolute;left:-10000px}footer{color:#b6aeb3;font-size:14px}#voteMessage,#shareMessage{min-height:28px} @media(max-width:700px){.cards{grid-template-columns:1fr}.card img{max-height:480px;object-fit:contain}header{flex-wrap:wrap}main{padding-top:10px}}</style><script src=\"/vote-client.js\" defer></script></head><body><header><a class=\"brand\" href=\"/\">ASRYO</a><nav aria-label=\"Main navigation\"><a href=\"/\">Home</a><a href=\"/about.html\">Our story</a></nav></header><main><p class=\"eyebrow\">ASRYO / Beyond Ordinary</p><h1>Choose our<br>first drop.</h1><p class=\"intro\">Three concepts. Your point of view. Which design would you wear? Share your preference to help guide the first ASRYO collection.</p><p class=\"intro\"><strong>Design previews only.</strong> These AI-generated images show concepts, not manufactured products. Samples, specifications, prices and launch dates are still being confirmed. Orders are not open.</p><form id=\"designVote\"><fieldset><legend>Choose your favourite concept</legend><div class=\"cards\"><label class=\"card\"><img src=\"/assets/asryo-speed-division-front.webp\" width=\"720\" height=\"900\" alt=\"Speed Division — AI-generated T-shirt design concept\" loading=\"lazy\"><input type=\"radio\" name=\"design\" value=\"speed-division\" required><strong>Speed Division</strong><span>Motorsport-inspired graphic energy.</span><span>AI-generated design preview</span></label><label class=\"card\"><img src=\"/assets/asryo-dream-front.webp\" width=\"720\" height=\"900\" alt=\"Dream Future — AI-generated T-shirt design concept\" loading=\"lazy\"><input type=\"radio\" name=\"design\" value=\"dream-future\" required><strong>Dream Future</strong><span>Expressive typography with a bold back design.</span><span>AI-generated design preview</span></label><label class=\"card\"><img src=\"/assets/shadowbound-front.webp\" width=\"720\" height=\"900\" alt=\"Shadowbound — AI-generated T-shirt design concept\" loading=\"lazy\"><input type=\"radio\" name=\"design\" value=\"shadowbound\" required><strong>Shadowbound</strong><span>Dark graphics with violet and electric-blue accents.</span><span>AI-generated design preview</span></label></div></fieldset><label class=\"trap\" aria-hidden=\"true\">Leave this blank<input name=\"website\" tabindex=\"-1\" autocomplete=\"off\"></label><p>By submitting, you agree to save your choice with an anonymous browser cookie. No name or email is requested. <a href=\"#privacy\">How this works</a>.</p><div class=\"actions\"><button id=\"saveVote\" type=\"submit\">Save my choice</button><button id=\"withdrawVote\" class=\"secondary\" type=\"button\" hidden>Withdraw my choice</button></div><p id=\"voteMessage\" role=\"status\" aria-live=\"polite\"></p><noscript>This form needs JavaScript to save your preference. Please enable JavaScript and reload.</noscript></form><section><h2>Bring another point of view.</h2><p>Share the concepts with someone who enjoys streetwear.</p><button id=\"shareVote\" class=\"secondary\" type=\"button\">Share the design vote</button><p id=\"shareMessage\" role=\"status\"></p></section><section id=\"privacy\" class=\"privacy\"><h2>A preference, not a purchase.</h2><p>This is informal design feedback, not a verified public poll or a product reservation. One saved choice per browser cookie can be updated or withdrawn here. Clearing cookies or using another browser can create another entry, so responses do not establish unique people.</p><p>We save the chosen design, a random browser identifier, the submission time and a broad referral category such as Instagram or LinkedIn. We do not request names, email addresses or free-text personal details. The cookie lasts 90 days; stored preferences expire after 90 days and are removed during subsequent submissions. Hosting providers may process standard request logs. This is separate from any future newsletter or order system.</p><p>No public vote counts or invented testimonials are displayed. Your preference helps research and does not guarantee that a design will be manufactured.</p></section></main><footer>ASRYO — BEYOND ORDINARY · Collection in development · <a href=\"/about.html\">Our story</a></footer></body></html>", "/vote-client.js": "const form = document.querySelector('#designVote');\nconst message = document.querySelector('#voteMessage');\nconst submit = document.querySelector('#saveVote');\nconst source = new URL(location.href).searchParams.get('utm_source') || 'direct';\nform.addEventListener('submit', async event => {\n  event.preventDefault(); submit.disabled = true; message.textContent = 'Saving your choice…';\n  try {\n    const response = await fetch('/api/design-vote', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({design:new FormData(form).get('design'),source,website:new FormData(form).get('website')})});\n    const result = await response.json();\n    if (!response.ok) throw new Error(result.error || 'Your vote could not be saved. Please try again.');\n    message.textContent = 'Your choice is saved. Thank you for helping shape the first ASRYO drop. You can change your choice here.';\n    document.querySelector('#withdrawVote').hidden = false;\n  } catch(error) { message.textContent = error.message; }\n  finally { submit.disabled = false; }\n});\ndocument.querySelector('#withdrawVote').addEventListener('click',async()=>{\n  try { const r=await fetch('/api/design-vote',{method:'DELETE'}); if(!r.ok)throw Error('Could not withdraw your choice. Please try again.'); form.reset();message.textContent='Your saved choice has been removed.';document.querySelector('#withdrawVote').hidden=true; } catch(e){message.textContent=e.message;}\n});\ndocument.querySelector('#shareVote').addEventListener('click',async()=>{\n  const data={title:'Choose the first ASRYO drop',text:'Which ASRYO streetwear concept would you wear? Design previews only.',url:'https://asryo.com/vote?utm_source=share&utm_medium=organic&utm_campaign=first_drop_vote'};\n  try { if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(data.url);document.querySelector('#shareMessage').textContent='Link copied. Share it with someone interested in streetwear.';} }catch(e){if(e.name!=='AbortError')document.querySelector('#shareMessage').textContent='Share this link: '+data.url;}\n});\nfetch('/api/design-vote').then(r=>{if(!r.ok)throw Error();return r.json();}).then(r=>{if(r.design){const input=[...form.elements].find(i=>i.name==='design'&&i.value===r.design);if(input)input.checked=true;message.textContent='Your previous choice is selected. You can update or withdraw it.';document.querySelector('#withdrawVote').hidden=false;}}).catch(()=>{});\n"};
const assets={"/assets/asryo-speed-division-front.webp": "", "/assets/asryo-dream-front.webp": "", "/assets/shadowbound-front.webp": ""};
const cookieName = '__Host-asryo-design-vote';
const ids = new Set(['speed-division','dream-future','shadowbound']);
const security = {'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'};
const json=(data,status=200,extra={})=>Response.json(data,{status,headers:{...security,'X-Robots-Tag':'noindex, nofollow',...extra}});
function visitor(req){const match=(req.headers.get('Cookie')||'').match(/(?:^|;\s*)__Host-asryo-design-vote=([0-9a-f-]{36})(?:;|$)/);return match&&/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(match[1])?match[1]:null;}
async function readInput(req){
  const reader=req.body?.getReader(); if(!reader)throw Error('Empty request');let bytes=0;const chunks=[];
  while(true){const {done,value}=await reader.read();if(done)break;bytes+=value.byteLength;if(bytes>1024){await reader.cancel();throw Error('Request too large');}chunks.push(value);}
  const body=new Uint8Array(bytes);let offset=0;for(const chunk of chunks){body.set(chunk,offset);offset+=chunk.length;}return JSON.parse(new TextDecoder().decode(body));
}
async function vote(req,env){
  const id=visitor(req), now=Math.floor(Date.now()/1000), cutoff=now-7776000;
  if(req.method==='GET'){
    const row=id?await env.FEEDBACK.prepare('SELECT design FROM design_preferences WHERE visitor_id = ? AND updated_at >= ?').bind(id,cutoff).first():null;
    return json({design:row?.design||null});
  }
  if(!['POST','DELETE'].includes(req.method))return json({error:'Method not allowed'},405,{'Allow':'GET, POST, DELETE'});
  if(req.headers.get('Origin')!=='https://asryo.com')return json({error:'Please submit from asryo.com.'},403);
  if(req.method==='DELETE'){
    if(id)await env.FEEDBACK.prepare('DELETE FROM design_preferences WHERE visitor_id = ?').bind(id).run();
    return json({ok:true},200,{'Set-Cookie':cookieName+'=; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=0'});
  }
  if(!req.headers.get('Content-Type')?.toLowerCase().startsWith('application/json'))return json({error:'Use JSON'},415);
  let body;try{body=await readInput(req);}catch{return json({error:'Invalid or oversized request'},400);}
  if(!body||!ids.has(body.design)||body.website)return json({error:'Choose one of the three concepts.'},400);
  const source=['linkedin','instagram','whatsapp','share','direct'].includes(body.source)?body.source:'other';
  const key=id||crypto.randomUUID();
  const results=await env.FEEDBACK.batch([
    env.FEEDBACK.prepare('DELETE FROM design_preferences WHERE updated_at < ?').bind(cutoff),
    env.FEEDBACK.prepare('INSERT INTO design_preferences (visitor_id, design, source, updated_at) SELECT ?, ?, ?, ? WHERE (SELECT COUNT(*) FROM design_preferences) < 10000 OR EXISTS (SELECT 1 FROM design_preferences WHERE visitor_id = ?) ON CONFLICT(visitor_id) DO UPDATE SET design = excluded.design, source = excluded.source, updated_at = excluded.updated_at').bind(key,body.design,source,now,key)
  ]);
  if(!results[1].meta.changes)return json({error:'Feedback collection is currently full. Please try later.'},503);
  return json({ok:true,design:body.design},200,{'Set-Cookie':cookieName+'='+key+'; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=7776000'});
}
const invitation='<section class="editorial-section" id="design-vote" aria-labelledby="designVoteTitle"><p class="editorial-eyebrow">HELP SHAPE DROP 001</p><h2 id="designVoteTitle">Which design would you wear?</h2><p>Explore Speed Division, Dream Future and Shadowbound, then save your favourite. Design previews only; orders are not open.</p><a class="editorial-button editorial-button-light" href="/vote">Choose our first drop</a></section>';
export default {async fetch(req,env,ctx){
  const url=new URL(req.url),p=url.pathname;
  if(url.hostname!=='asryo.com')return storefront.fetch(req,env,ctx);
  try{
    if(Object.hasOwn(assets,p)&&['GET','HEAD'].includes(req.method))return new Response(req.method==='HEAD'?null:Uint8Array.from(atob(assets[p]),c=>c.charCodeAt(0)),{headers:{...security,'Content-Type':'image/webp','Cache-Control':'public, max-age=86400'}});
    if(p==='/api/design-vote')return await vote(req,env);
    if(Object.hasOwn(pages,p)){
      if(!['GET','HEAD'].includes(req.method))return new Response('Method not allowed',{status:405,headers:{...security,Allow:'GET, HEAD'}});
      return new Response(req.method==='HEAD'?null:pages[p],{headers:{...security,'Content-Type':p.endsWith('.js')?'text/javascript; charset=utf-8':'text/html; charset=utf-8','X-Robots-Tag':p.endsWith('.js')?'noindex':'index, follow, max-image-preview:large'}});
    }
    if(p==='/sitemap.xml'&&['GET','HEAD'].includes(req.method))return new Response(req.method==='HEAD'?null:'<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>https://asryo.com/</loc></url><url><loc>https://asryo.com/about.html</loc></url><url><loc>https://asryo.com/vote</loc></url></urlset>',{headers:{...security,'Content-Type':'application/xml; charset=utf-8'}});
    const response=await storefront.fetch(req,env,ctx);
    if(p==='/'&&req.method==='GET'&&response.ok){
      return new HTMLRewriter()
        .on('#featured',{element(e){e.before(invitation,{html:true});}})
        .on('#early-access',{element(e){e.setInnerContent('<div class="editorial-early-copy"><p class="editorial-eyebrow">YOUR POINT OF VIEW</p><h2>Help shape the first drop.</h2><p>Save a design preference without providing your email. This is informal research, not an order or newsletter signup.</p><a class="editorial-button editorial-button-light" href="/vote">Choose your favourite</a></div>',{html:true});}})
        .on('a[href="#early-access"]',{element(e){e.setAttribute('href','/vote');e.setInnerContent('Choose the first drop');}})
        .transform(response);
    }
    return response;
  }catch(error){console.error(JSON.stringify({event:'feedback_failure',path:p,name:error.name}));return json({error:'Feedback is temporarily unavailable. Please try again later.'},503);}
}};
